"""Turn the measured HTML guide into a self-contained, responsive slide deck."""

from html import escape
import re


def as_slides(document, *, verification, notice, details):
    hero = re.search(
        r'<div class="hero">(.*?)</div>\s*<section class="chapter"', document, re.S
    ).group(1)
    chapters = dict(
        re.findall(
            r'<section class="chapter" id="([^"]+)">(.*?)</section>', document, re.S
        )
    )
    metrics = chapters["results"].split('<div class="table-scroll">', 1)[0]
    titles = ["Overview", "System", "Memory", "TinyFish", "Results", "Verification"]
    ids = ["intro", "system", "memory", "tinyfish", "results", "verification"]
    items = "".join(
        f'<option value="{identifier}">{index + 1}. {title}</option>'
        for index, (identifier, title) in enumerate(zip(ids, titles))
    )
    statuses = "".join(
        f'<article class="check-card"><span>{escape(label)}</span><strong>{escape(value)}</strong><small>{escape(scope)}</small></article>'
        for label, value, scope in verification
    )
    verification_html = f'<div class="eyebrow">06 / Verification</div><h2>Tested outcomes. Visible limits.</h2><div class="check-grid">{statuses}</div>{notice}<button class="report-button" id="open-reports" type="button">Measurement details &amp; reports ↗</button>'
    contents = [
        hero,
        chapters["system"],
        chapters["memory"],
        chapters["tinyfish"],
        metrics,
        verification_html,
    ]
    slides = "".join(
        f'<section class="slide {"cover" if index == 0 else ""}" id="{identifier}" role="group" aria-roledescription="slide" aria-label="{index + 1} of 6: {title}"{ "" if index == 0 else " hidden"}><div class="slide-content">{content}</div></section>'
        for index, (identifier, title, content) in enumerate(zip(ids, titles, contents))
    )
    return (
        """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TinyFish × Iron Web · presentation</title><meta name="description" content="Six slides explaining the multi-agent system, shared memory, TinyFish research and measured results.">
<style>
:root{--ink:#142f2c;--muted:#41615a;--green:#174c40;--line:#cbd9cd;--paper:#f7f8f1;--soft:#eaf0e6}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden}body{height:100dvh;display:grid;grid-template-rows:auto minmax(0,1fr) auto;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}button,select{font:inherit}button,a,select{-webkit-tap-highlight-color:transparent}a{color:var(--green);text-underline-offset:4px}button{cursor:pointer}button:disabled{opacity:.35;cursor:default}.top{border-bottom:1px solid var(--line)}.bar{max-width:1280px;margin:auto;padding:15px 28px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{font-weight:850;letter-spacing:-.03em;color:var(--green);text-decoration:none;white-space:nowrap}.toolbar{display:flex;align-items:center;gap:12px}.toolbar select{max-width:180px;padding:7px 12px;border:1px solid var(--line);border-radius:7px;background:transparent;color:var(--ink);font-size:12px}.fullscreen{border:0;background:none;color:var(--green);font-size:12px;padding:8px}.deck{position:relative;min-height:0;padding:clamp(16px,3vh,32px) clamp(20px,5vw,72px);touch-action:pan-y}.slide{width:100%;height:100%;min-height:0;display:grid;place-items:center;overflow:hidden}.slide-content{width:100%;max-width:1140px;transform-origin:center;flex-shrink:0}.slide[hidden]{display:none!important}.eyebrow,.scope{text-transform:uppercase;letter-spacing:.09em;font-size:10px;font-weight:750;color:var(--muted)}h1{font-size:clamp(36px,5.3vw,76px);letter-spacing:-.055em;line-height:1.08;margin:20px 0 28px;max-width:20ch}.cover .slide-content>p{font-size:clamp(16px,1.8vw,22px);max-width:65ch;color:var(--muted)}h2{font-size:clamp(25px,3.2vw,42px);line-height:1.15;letter-spacing:-.035em;margin:10px 0 25px}h3{font-size:16px;line-height:1.35;margin:9px 0}p{margin:10px 0}.pill{display:inline-block;background:var(--soft);border:1px solid var(--line);padding:7px 12px;border-radius:20px;font-size:12px;margin:12px 7px 0 0}.flow{list-style:none;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin:22px 0;padding:0}.flow li{background:var(--green);color:#f3fff4;padding:20px 14px;border-radius:10px;font-size:12px}.flow b{display:block;color:#acdabd;font-size:10px;margin-bottom:9px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{padding:20px;background:white;border:1px solid var(--line);border-radius:12px}.card p{font-size:13px;color:var(--muted)}.features{display:grid;grid-template-columns:1fr 1fr;gap:30px 24px;margin:26px 0}.features>div{border-left:3px solid #377859;padding:8px 20px}.features h3{font-size:21px}.features p{font-size:16px;color:var(--muted);max-width:40ch}#tinyfish .slide-content>p:not(.method){font-size:clamp(16px,2.2vw,24px);max-width:75ch;line-height:1.65}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.metric{background:var(--soft);border:1px solid var(--line);border-radius:12px;padding:20px}.metric strong{display:block;font-size:clamp(30px,3.5vw,44px);line-height:1.15;margin-top:13px;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.metric h3{margin:12px 0 7px}.metric p{font-size:12px;color:var(--muted);line-height:1.5}.method{font-size:12px;color:var(--muted);margin:20px 0 0;max-width:100ch}.notice{border-left:3px solid #a26c1f;background:#f8eedc;padding:13px 18px;font-size:12px;margin:20px 0}.check-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.check-card{padding:16px 20px;background:white;border:1px solid var(--line);border-radius:12px;display:flex;flex-direction:column;gap:5px}.check-card span{font-size:12px;font-weight:700}.check-card strong{font-size:28px;line-height:1.25}.check-card small{font-size:11px;color:var(--muted)}.controls{border-top:1px solid var(--line);background:var(--paper)}.control-bar{max-width:1280px;margin:auto;display:grid;grid-template-columns:1fr auto 1fr;gap:16px;align-items:center;padding:14px 28px}.hint{font-size:11px;color:var(--muted)}.navigation{display:flex;align-items:center;gap:16px}.navigation button,.report-button{padding:9px 16px;border:1px solid var(--line);border-radius:7px;background:transparent;color:var(--green);font-size:12px;font-weight:700}.navigation button:last-child,.report-button{background:var(--green);border-color:var(--green);color:white}.counter{font-variant-numeric:tabular-nums;font-size:12px;min-width:45px;text-align:center}.branch{font-size:10px;color:var(--muted);justify-self:end}.progress{height:3px;background:var(--soft)}.progress span{display:block;height:100%;background:#377859;width:16.666%}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #4f9970;outline-offset:4px}h1:focus,h2:focus{outline:none}.sources{display:flex;flex-wrap:wrap;gap:12px;font-size:13px}.sources a{padding:8px 10px;background:var(--soft);border-radius:5px}dialog{max-width:650px;width:calc(100% - 32px);max-height:85dvh;border:1px solid var(--line);border-radius:14px;padding:26px;background:var(--paper);color:var(--ink);overflow:auto}dialog::backdrop{background:#0d2925aa}.dialog-top{display:flex;justify-content:space-between;align-items:center;gap:20px}.dialog-top h2{font-size:24px;margin:0}.dialog-top button{border:0;background:var(--soft);padding:8px 12px;border-radius:6px}dialog p{font-size:13px;line-height:1.7}.dialog-note{color:var(--muted);font-size:11px;margin-top:20px}
@media(max-width:760px){.bar{padding:12px 18px;gap:8px}.brand{font-size:12px}.toolbar{gap:4px}.toolbar select{max-width:125px;padding:6px;font-size:11px}.fullscreen{font-size:0;padding:6px}.fullscreen:before{content:'⛶';font-size:20px}.deck{padding:18px 20px}.flow{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:15px 0}.flow li{padding:13px 10px;font-size:11px}.flow b{font-size:9px;margin-bottom:5px}.grid{gap:10px}.card{padding:12px}.card h3{font-size:13px}.card p{font-size:11px}.metrics,.check-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric{padding:13px}.metric h3{font-size:13px}.metric strong{font-size:32px;margin-top:8px}.metric p{font-size:11px;margin:6px 0 0}.scope{font-size:8px}.method{font-size:10px;margin-top:14px}.features{gap:20px 14px}.features>div{padding:4px 13px}.features h3{font-size:18px}.features p{font-size:13px}.check-card{padding:12px}.check-card strong{font-size:23px}.check-card small{font-size:10px}.notice{font-size:11px;padding:12px;margin:15px 0}.control-bar{padding:12px 18px;grid-template-columns:1fr}.navigation{justify-content:space-between}.hint,.branch{display:none}.eyebrow{font-size:9px}h2{margin-bottom:18px}#tinyfish .method{font-size:12px}}
@media(max-width:450px){.grid{grid-template-columns:1fr;gap:8px}.card{padding:10px 13px}.card h3{margin:0 0 5px}.card p{margin:0}.features{grid-template-columns:1fr 1fr}.features h3{font-size:16px}.features p{font-size:12px}.pill{font-size:10px}.metric p{font-size:10px}.check-card span{font-size:11px}.check-card strong{font-size:22px}.report-button{font-size:11px}}
@media print{html,body{height:auto;overflow:visible;display:block}.top,.controls,dialog,.report-button{display:none!important}.deck{padding:0}.slide,.slide[hidden]{display:grid!important;min-height:95vh;height:95vh;break-after:page;padding:30px;overflow:visible}.slide:last-child{break-after:auto}.slide-content{transform:none!important}.metrics,.check-grid{grid-template-columns:repeat(3,1fr)}.metric,.flow li{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
.slide{display:flex;align-items:center;justify-content:center}
</style></head><body>
<header class="top"><div class="bar"><a class="brand" href="#intro">IRON WEB × TINYFISH</a><div class="toolbar"><label class="sr-only" for="slide-jump">Go to slide</label><select id="slide-jump">"""
        + items
        + """</select><button id="fullscreen" class="fullscreen" type="button" aria-label="Enter fullscreen">Present fullscreen</button></div></div></header>
<main class="deck" id="main" aria-label="System presentation">"""
        + slides
        + """</main>
<footer class="controls"><div class="control-bar"><span class="hint">← → / Space to navigate · F for fullscreen</span><div class="navigation"><button id="previous" type="button" aria-label="Previous slide">← Previous</button><span id="counter" class="counter" aria-live="polite">1 / 6</span><button id="next" type="button" aria-label="Next slide">Next →</button></div><span class="branch">Feature branch · unmerged</span></div><div class="progress" role="progressbar" aria-label="Presentation progress" aria-valuemin="1" aria-valuemax="6" aria-valuenow="1"><span></span></div></footer>
<dialog id="reports" aria-labelledby="reports-title"><div class="dialog-top"><h2 id="reports-title">Measurement details</h2><button id="close-reports" type="button" aria-label="Close reports">Close ×</button></div>"""
        + details
        + """<p class="dialog-note">codex/tinyfish-memory-refresh · Unmerged. Prices are estimates; reservations are simulated.</p></dialog>
<script>
(()=>{'use strict';const slides=[...document.querySelectorAll('.slide')],jump=document.querySelector('#slide-jump'),previous=document.querySelector('#previous'),next=document.querySelector('#next'),counter=document.querySelector('#counter'),progress=document.querySelector('.progress'),reports=document.querySelector('#reports'),fullscreen=document.querySelector('#fullscreen');let current=0,start=null;function fit(){const slide=slides[current],content=slide.querySelector('.slide-content');content.style.transform='';const scale=Math.min(1,slide.clientHeight/Math.max(content.scrollHeight,1),slide.clientWidth/Math.max(content.scrollWidth,1));content.style.transform='scale('+scale+')';}function show(index,focus=false){current=Math.max(0,Math.min(slides.length-1,index));slides.forEach((slide,i)=>slide.hidden=i!==current);jump.value=slides[current].id;previous.disabled=current===0;next.disabled=current===slides.length-1;counter.textContent=(current+1)+' / '+slides.length;progress.setAttribute('aria-valuenow',current+1);progress.querySelector('span').style.width=((current+1)/slides.length*100)+'%';try{history.replaceState(null,'','#'+slides[current].id);}catch{}requestAnimationFrame(fit);if(focus){const heading=slides[current].querySelector('h1,h2');heading.tabIndex=-1;heading.focus({preventScroll:true});}}function fromHash(){const id=location.hash.slice(1);show(Math.max(0,slides.findIndex(slide=>slide.id===id)));}async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{fullscreen.textContent='Fullscreen unavailable';}}previous.addEventListener('click',()=>show(current-1,true));next.addEventListener('click',()=>show(current+1,true));jump.addEventListener('change',()=>show(slides.findIndex(slide=>slide.id===jump.value),true));window.addEventListener('hashchange',fromHash);window.addEventListener('resize',fit);new ResizeObserver(fit).observe(document.querySelector('.deck'));document.fonts.ready.then(fit);fullscreen.addEventListener('click',toggleFullscreen);document.addEventListener('fullscreenchange',()=>{fullscreen.textContent=document.fullscreenElement?'Exit fullscreen':'Present fullscreen';fullscreen.setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');requestAnimationFrame(fit);});document.querySelector('#open-reports').addEventListener('click',()=>reports.showModal());document.querySelector('#close-reports').addEventListener('click',()=>reports.close());document.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||reports.open||event.target.closest('input,select,textarea,[contenteditable=true]'))return;if(event.key===' '&&event.target.closest('button,a'))return;const keys=['ArrowRight','PageDown',' ','ArrowLeft','PageUp','Home','End','f','F'];if(!keys.includes(event.key))return;event.preventDefault();if(['ArrowRight','PageDown',' '].includes(event.key))show(current+1,true);else if(['ArrowLeft','PageUp'].includes(event.key))show(current-1,true);else if(event.key==='Home')show(0,true);else if(event.key==='End')show(slides.length-1,true);else toggleFullscreen();});const deck=document.querySelector('.deck');deck.addEventListener('touchstart',event=>{if(event.target.closest('button,a,select'))return;start={x:event.touches[0].clientX,y:event.touches[0].clientY};},{passive:true});deck.addEventListener('touchend',event=>{if(!start)return;const dx=event.changedTouches[0].clientX-start.x,dy=event.changedTouches[0].clientY-start.y;start=null;if(Math.abs(dx)>60&&Math.abs(dy)<60)show(current+(dx<0?1:-1),true);},{passive:true});fromHash();})();
</script></body></html>"""
    )
